#pragma once

// stx_textlayout's shared property table (include/stxlib/textlayout.hpp):
// one 32-bit record per code point, generated by
// tools/gen_textlayout_tables.py (textlayout_tables.inc), and the lookups
// over it. Header only, so the tests read the tables the library runs.
//
// Record: Bidi_Class in bits 0-4, BRACKET (a Bidi_Paired_Bracket) in bit
// 5, MIRRORED in bit 6, the line-break symbol in bits 8-14, Script in bits
// 16-23, the Script_Extensions set in bits 24-31 (0: none beyond Script).
//
// Every loop here is a binary search that halves [low, high) each step:
// at most 8 steps over the 130 brackets, 9 over the 438 mirrors.

#include "stxlib/types.hpp"

namespace stxlib::textlayout::tables {

struct BracketEntry final {
    u32 code_point;
    u32 pair;
    u32 key;
    u32 opens;
};

struct MirrorEntry final {
    u32 code_point;
    u32 mirror;
};

#include "algorithms/textlayout/textlayout_tables.inc"

inline constexpr u32 class_bits = 0x1fu;
inline constexpr u32 bracket_bit = 0x20u;
inline constexpr u32 mirrored_bit = 0x40u;
inline constexpr u32 symbol_shift = 8;
inline constexpr u32 symbol_bits = 0x7fu;
inline constexpr u32 script_shift = 16;
inline constexpr u32 script_bits = 0xffu;
inline constexpr u32 extension_shift = 24;
inline constexpr u32 opens_bit = 0x80000000u;
inline constexpr u32 highest_code_point = 0x10ffffu;
inline constexpr u32 replacement_character = 0xfffdu;

// The generated table's value ranges, checked at compile time against the
// arrays the code indexes with them (A-stxlib-textlayout-01-F4), so that a
// regenerated table that drifts from the code fails to compile instead of
// reading outside static data. Each walk is linear in its table.
static_assert((static_cast<u32>(sizeof(property_stage1) / sizeof(property_stage1[0])) << property_block_shift) ==
                  highest_code_point + 1,
              "stx_textlayout: stage 1 covers every code point");
static_assert(property_block_mask + 1 == (1u << property_block_shift), "stx_textlayout: the block mask");
static_assert(lb_symbol_count < (1u << lb_dfa_shift), "stx_textlayout: a symbol fits an automaton row");
static_assert(lb_symbol_count <= symbol_bits && script_count <= script_bits + 1 && script_extension_set_count <= 0xffu,
              "stx_textlayout: the record's fields hold their counts");

[[nodiscard]] constexpr bool stage1_in_range() noexcept {
    for (const u16 block : property_stage1) {
        if (static_cast<usize>(block) >= property_block_count) return false;
    }
    return true;
}

// Every record: Bidi_Class below bidi_class_count (23: the analysis's
// per-class arrays), the symbol below lb_symbol_count, Script below
// script_count, the set at most script_extension_set_count.
[[nodiscard]] constexpr bool records_in_range(const u32 class_count) noexcept {
    for (const u32 (&block)[property_block_mask + 1] : property_stage2) {
        for (const u32 properties : block) {
            if ((properties & class_bits) >= class_count) return false;
            if (((properties >> symbol_shift) & symbol_bits) >= lb_symbol_count) return false;
            if (((properties >> script_shift) & script_bits) >= script_count) return false;
            if ((properties >> extension_shift) > script_extension_set_count) return false;
        }
    }
    return true;
}

[[nodiscard]] constexpr bool extensions_in_range() noexcept {
    constexpr usize member_count = sizeof(script_extension_members) / sizeof(script_extension_members[0]);
    if (script_extension_begin[0] != 0) return false;
    for (u32 set = 1; set <= script_extension_set_count; ++set) {
        if (script_extension_begin[set] < script_extension_begin[set - 1]) return false;
    }
    if (static_cast<usize>(script_extension_begin[script_extension_set_count]) > member_count) return false;
    for (const u8 member : script_extension_members) {
        if (static_cast<u32>(member) >= script_count) return false;
    }
    return true;
}

static_assert(stage1_in_range(), "stx_textlayout: every stage-1 entry names a block");
static_assert(extensions_in_range(), "stx_textlayout: the extension sets lie within their members");

// The records of U+0000 to U+007F, contiguous (block 0).
inline constexpr const u32* ascii_records = property_stage2[0];
static_assert(property_stage1[0] == 0, "stx_textlayout: block 0 is the ASCII block");

// The record of a code point. Requirement: code_point <= 0x10FFFF.
[[nodiscard]] constexpr u32 record(const u32 code_point) noexcept {
    const u32 block = property_stage1[code_point >> property_block_shift];
    const u32 result = property_stage2[block][code_point & property_block_mask];
    return result;
}

// The record of an element of a code point array: U+FFFD's for a value
// that is not a scalar value.
[[nodiscard]] constexpr u32 record_of_input(const u32 code_point) noexcept {
    if (code_point > highest_code_point || (code_point >= 0xd800u && code_point <= 0xdfffu)) {
        const u32 replaced = record(replacement_character);
        return replaced;
    }
    const u32 result = record(code_point);
    return result;
}

[[nodiscard]] constexpr u32 symbol_of(const u32 properties) noexcept {
    return (properties >> symbol_shift) & symbol_bits;
}

[[nodiscard]] constexpr u32 script_in(const u32 properties) noexcept {
    return (properties >> script_shift) & script_bits;
}

// The index of the first bracket entry not below `code_point`.
[[nodiscard]] constexpr usize bracket_index(const u32 code_point) noexcept {
    usize low = 0;
    usize high = bidi_bracket_count;
    while (low < high) {
        const usize middle = low + (high - low) / 2;
        if (bidi_brackets[middle].code_point < code_point) {
            low = middle + 1;
        } else {
            high = middle;
        }
    }
    return low;
}

// The BD16 key of a bracket code point, with opens_bit when it opens; 0
// for a code point that is no bracket.
[[nodiscard]] constexpr u32 bracket_key(const u32 code_point) noexcept {
    const usize index = bracket_index(code_point);
    u32 result = 0;
    if (index < bidi_bracket_count && bidi_brackets[index].code_point == code_point) {
        result = bidi_brackets[index].key | (bidi_brackets[index].opens != 0 ? opens_bit : 0u);
    }
    return result;
}

// Whether `script` is the record's Script or in its Script_Extensions set
// (at most 23 members, searched in order).
[[nodiscard]] constexpr bool script_extends(const u32 properties, const u32 script) noexcept {
    if (script_in(properties) == script) return true;
    const u32 set = properties >> extension_shift;
    if (set == 0) return false;
    const u32 end = script_extension_begin[set];
    for (u32 index = script_extension_begin[set - 1]; index < end; ++index) {
        if (script_extension_members[index] == script) return true;
    }
    return false;
}

} // namespace stxlib::textlayout::tables
